import React, { useState } from 'react';
import { Student, AttendanceRecord } from '../types';

interface AttendanceSheetProps {
  students: Student[];
  onSave: (record: AttendanceRecord) => void;
}

const AttendanceSheet: React.FC<AttendanceSheetProps> = ({ students, onSave }) => {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const today = new Date().toISOString().split('T')[0];

  const toggleStudent = (id: string) => {
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleSelectAll = () => {
    if (selectedIds.length === students.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(students.map(s => s.id));
    }
  };

  const handleSave = () => {
    onSave({
      date: new Date().toISOString(),
      presentStudentIds: selectedIds
    });
    alert('Attendance saved successfully!');
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
      <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
        <div>
          <h3 className="text-lg font-bold text-slate-800">Daily Attendance</h3>
          <p className="text-sm text-slate-500">Mark students present for {today}</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={handleSelectAll}
            className="px-4 py-2 text-sm font-medium text-slate-600 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 transition-colors"
          >
            {selectedIds.length === students.length ? 'Deselect All' : 'Select All'}
          </button>
          <button 
            onClick={handleSave}
            className="px-4 py-2 text-sm font-medium text-white bg-indigo-600 rounded-lg hover:bg-indigo-700 transition-colors shadow-sm"
          >
            Save Attendance
          </button>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead>
            <tr className="border-b border-slate-100 bg-slate-50/30">
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider w-16">Status</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Student</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Grade</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase tracking-wider">Email</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {students.map((student) => (
              <tr 
                key={student.id} 
                onClick={() => toggleStudent(student.id)}
                className={`group cursor-pointer hover:bg-indigo-50/30 transition-colors ${selectedIds.includes(student.id) ? 'bg-indigo-50/10' : ''}`}
              >
                <td className="px-6 py-4">
                  <div className={`w-6 h-6 rounded-md border flex items-center justify-center transition-all ${
                    selectedIds.includes(student.id) 
                      ? 'bg-indigo-600 border-indigo-600 text-white' 
                      : 'border-slate-300 bg-white group-hover:border-indigo-400'
                  }`}>
                    {selectedIds.includes(student.id) && <span className="text-xs">✓</span>}
                  </div>
                </td>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-3">
                    <img src={student.avatar} className="w-10 h-10 rounded-full border border-slate-200" alt={student.name} />
                    <span className="text-sm font-semibold text-slate-700">{student.name}</span>
