import React, { useState } from 'react';
import { generateActivityIdeas } from '../services/geminiService';
import { ActivitySuggestion, Activity } from '../types';

interface ActivityPlannerProps {
  onAddActivity: (activity: Activity) => void;
}

const ActivityPlanner: React.FC<ActivityPlannerProps> = ({ onAddActivity }) => {
  const [topic, setTopic] = useState('');
  const [grade, setGrade] = useState('9');
  const [subject, setSubject] = useState('Science');
  const [suggestions, setSuggestions] = useState<ActivitySuggestion[]>([]);
  const [loading, setLoading] = useState(false);

  const handleGenerate = async () => {
    if (!topic) return;
    setLoading(true);
    try {
      const results = await generateActivityIdeas(grade, subject, topic);
      setSuggestions(results);
    } catch (err) {
      alert('Failed to generate ideas. Please check your API key.');
    } finally {
      setLoading(false);
    }
  };

  const handleAddSuggestion = (s: ActivitySuggestion) => {
    const newActivity: Activity = {
      id: Math.random().toString(36).substr(2, 9),
      title: s.title,
      subject,
      description: s.description,
      duration: s.duration,
      learningObjectives: s.learningObjectives,
      materials: s.materials,
      status: 'planned'
    };
    onAddActivity(newActivity);
    setSuggestions(prev => prev.filter(item => item !== s));
    alert('Activity added to your curriculum plan!');
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      {/* Search Section */}
      <div className="lg:col-span-1 space-y-6">
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
            <span className="text-indigo-600">🪄</span> AI Curriculum Assistant
          </h3>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Subject</label>
              <select 
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              >
                <option>Science</option>
                <option>Mathematics</option>
                <option>English Literature</option>
                <option>History</option>
                <option>Geography</option>
                <option>Computer Science</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Grade Level</label>
              <input 
                type="text" 
                value={grade}
                onChange={(e) => setGrade(e.target.value)}
                placeholder="e.g. 9 or 10A"
                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Topic / Keywords</label>
              <textarea 
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
                placeholder="e.g. Molecular biology, climate change, python lists..."
                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none h-32 resize-none"
              />
            </div>
            <button 
              onClick={handleGenerate}
              disabled={loading || !topic}
              className={`w-full py-3 rounded-lg font-semibold text-white transition-all ${
                loading ? 'bg-slate-400 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700 shadow-md active:scale-95'
              }`}
            >
              {loading ? 'Generating Suggestions...' : 'Generate Activity Ideas'}
            </button>
          </div>
        </div>
      </div>

      {/* Results Section */}
      <div className="lg:col-span-2 space-y-6">
        {loading ? (
          <div className="h-64 flex flex-col items-center justify-center bg-white rounded-xl border border-dashed border-slate-300">
             <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mb-4"></div>
             <p className="text-slate-500 font-medium">Gemini is brainstorming creative activities...</p>
          </div>
        ) : suggestions.length > 0 ? (
          <div className="space-y-4">
            <h3 className="text-xl font-bold text-slate-800">Generated Ideas</h3>
            {suggestions.map((s, idx) => (
              <div key={idx} className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm hover:border-indigo-200 transition-colors group">
                <div className="flex justify-between items-start mb-4">
                  <div className="flex-1">
                    <h4 className="text-lg font-bold text-slate-800 group-hover:text-indigo-600 transition-colors">{s.title}</h4>
                    <span className="inline-block px-2 py-1 bg-slate-100 text-slate-600 text-[10px] font-bold uppercase rounded mt-1">
                      {s.duration}
                    </span>
                  </div>
                  <button 
                    onClick={() => handleAddSuggestion(s)}
                    className="p-2 bg-emerald-50 text-emerald-600 rounded-lg hover:bg-emerald-600 hover:text-white transition-all text-xs font-bold"
                  >
                    Add to Plan +
                  </button>
                </div>
                <p className="text-slate-600 text-sm mb-4 leading-relaxed">{s.description}</p>

                <div className="grid md:grid-cols-2 gap-4">
                  <div>
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Objectives</h5>
                    <ul className="text-sm text-slate-600 space-y-1">
                      {s.learningObjectives.map((obj, i) => <li key={i} className="flex items-center gap-2">
                        <span className="text-indigo-400 text-xs">•</span> {obj}
                      </li>)}
                    </ul>
                  </div>
                  <div>
                    <h5 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Materials</h5>
                    <div className="flex flex-wrap gap-2">
                      {s.materials.map((mat, i) => (
                        <span key={i} className="px-2 py-1 bg-indigo-50 text-indigo-700 text-xs rounded-md">
                          {mat}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="h-full flex flex-col items-center justify-center bg-white rounded-xl border border-dashed border-slate-300 p-12 text-center">
            <div className="text-4xl mb-4">💡</div>
            <h3 className="text-lg font-bold text-slate-800">No suggestions yet</h3>
            <p className="text-slate-500 max-w-xs">Fill out the form on the left to get AI-powered activity ideas for your classroom.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ActivityPlanner;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AttendanceSheet from './components/AttendanceSheet';
import ActivityPlanner from './components/ActivityPlanner';
import { View, Student, Activity, AttendanceRecord } from './types';
import { INITIAL_STUDENTS, INITIAL_ACTIVITIES } from './constants';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [students] = useState<Student[]>(INITIAL_STUDENTS);
  const [activities, setActivities] = useState<Activity[]>(INITIAL_ACTIVITIES);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);

  const handleAddActivity = (newAct: Activity) => {
    setActivities(prev => [newAct, ...prev]);
  };

  const handleSaveAttendance = (record: AttendanceRecord) => {
    setAttendance(prev => [...prev, record]);
  };

  const renderView = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard students={students} attendance={attendance} activities={activities} />;
      case 'attendance':
        return <AttendanceSheet students={students} onSave={handleSaveAttendance} />;
      case 'students':
        return (
          <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
            <h3 className="text-lg font-bold mb-6">Student Directory</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center gap-4 p-4 border border-slate-100 rounded-xl hover:shadow-md transition-shadow">
                  <img src={s.avatar} className="w-12 h-12 rounded-full border-2 border-indigo-100" alt={s.name} />
                  <div>
                    <h4 className="font-semibold">{s.name}</h4>
                    <p className="text-xs text-slate-500">{s.grade} • {s.email}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'planner':
        return <ActivityPlanner onAddActivity={handleAddActivity} />;
      default:
        return <Dashboard students={students} attendance={attendance} activities={activities} />;
    }
  };

  return (
    <Layout currentView={currentView} onViewChange={setCurrentView}>
      {renderView()}
    </Layout>
  );
};

export default App;

