import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import AttendanceSheet from './components/AttendanceSheet';
import ActivityPlanner from './components/ActivityPlanner';
import StudentDetails from './components/StudentDetails';
import StudentDirectory from './components/StudentDirectory';
import { View, Student, Activity, AttendanceRecord } from './types';
import { INITIAL_STUDENTS, INITIAL_ACTIVITIES } from './constants';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [students] = useState<Student[]>(INITIAL_STUDENTS);
  const [activities, setActivities] = useState<Activity[]>(INITIAL_ACTIVITIES);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);

  const handleAddActivity = (newAct: Activity) => {
    setActivities(prev => [newAct, ...prev]);
  };

  const handleSaveAttendance = (record: AttendanceRecord) => {
    setAttendance(prev => [...prev, record]);
  };

  const selectedStudent = students.find(s => s.id === selectedStudentId);

  const renderView = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard students={students} attendance={attendance} activities={activities} />;
      case 'attendance':
        return <AttendanceSheet students={students} onSave={handleSaveAttendance} />;
      case 'students':
        if (selectedStudent) {
          return (
            <StudentDetails 
              student={selectedStudent} 
              attendanceHistory={attendance}
              onBack={() => setSelectedStudentId(null)} 
            />
          );
        }
        return (
          <StudentDirectory 
            students={students} 
            onSelectStudent={setSelectedStudentId} 
          />
        );
      case 'planner':
        return <ActivityPlanner onAddActivity={handleAddActivity} />;
      default:
        return <Dashboard students={students} attendance={attendance} activities={activities} />;
    }
  };

  return (
    <Layout currentView={currentView} onViewChange={(view) => {
      setCurrentView(view);
      setSelectedStudentId(null); // Reset selection when switching main tabs
    }}>
      {renderView()}
    </Layout>
  );
};

