                    as.status === 'graded' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-600'
                  }`}>
                    {as.subject === 'Science' ? '🧪' : as.subject === 'Math' ? '📐' : '📖'}
